$logPath = 'C:\Windows\Setup\Scripts\InstallVirtioDrivers.log'; function Write-Log( [string] $msg ) { $ts = [datetime]::Now.ToString( 'yyyy-MM-dd HH:mm:ss' ); Add-Content -LiteralPath $logPath -Value ( $ts + ' ' + $msg ); }; Write-Log 'InstallVirtioDrivers starting.'; $driverRoot = $null; foreach( $letter in 'DEFGHIJKLMNOPQRSTUVWXYZ'.ToCharArray() ) { $cand = $letter + ':\$WinPEDriver$'; if( Test-Path -LiteralPath $cand ) { $driverRoot = $cand; break; } }; if( -not $driverRoot ) { Write-Log 'No $WinPEDriver$ folder found on install media. Skipping (boot-critical drivers were already injected offline via DISM).'; return; }; Write-Log ( 'Found driver folder at ' + $driverRoot ); try { $out = & pnputil.exe /add-driver ( $driverRoot + '\*.inf' ) /subdirs /install 2>&1 | Out-String; Write-Log $out; Write-Log ( 'pnputil exit code: ' + $LASTEXITCODE ); } catch { Write-Log ( 'pnputil failed: ' + $_.Exception.Message ); }; Write-Log 'InstallVirtioDrivers finished.';
